"""Randomised differential test between the engine and the naive reference."""
import json
import random
import sys

sys.path.insert(0, '/workspace/submission')
sys.path.insert(0, '/workspace/tmp/work')

import ref
from utils import run_request


def make_borders(rng, upper, count):
    points = {0, upper}
    while len(points) < count + 1:
        points.add(rng.randint(1, upper - 1))
    return sorted(points)


def make_run(rng, packet_counter):
    M = rng.randint(1, 4)
    L = rng.randint(1, 3)
    upper = rng.choice([5, 8, 16, 32, 100])
    ranges = rng.randint(1, 4)
    borders = make_borders(rng, upper, ranges)
    kind = rng.choice(['fifo', 'sp', 'sff', 'wfq'])
    flows = list(range(rng.randint(1, 3)))
    if kind == 'sp':
        policy = {'kind': 'sp', 'levels': [[f, rng.randint(0, 20)] for f in flows]}
    elif kind == 'wfq':
        policy = {'kind': 'wfq', 'weights': [[f, rng.randint(1, 8)] for f in flows]}
    else:
        policy = {'kind': kind}
    events = []
    saved = []
    live_ids = []
    next_id = packet_counter
    for _ in range(rng.randint(1, 40)):
        choice = rng.random()
        if choice < 0.4:
            packet_id = next_id
            next_id += 1
            events.append(['enqueue', packet_id, rng.choice(flows),
                           rng.randint(1, 12), rng.randint(0, 30)])
            live_ids.append(packet_id)
        elif choice < 0.58:
            events.append(['dequeue', rng.randint(1, 4)])
        elif choice < 0.63:
            events.append(['sample'])
        elif choice < 0.68:
            count = rng.randint(1, 3)
            events.append(['repartition', make_borders(rng, upper, count)])
        elif choice < 0.74:
            target = rng.choice(live_ids) if live_ids and rng.random() < 0.8 else rng.randint(0, 40)
            events.append(['cancel', target])
        elif choice < 0.8:
            target = rng.choice(live_ids) if live_ids and rng.random() < 0.8 else rng.randint(0, 40)
            events.append(['inspect', target])
        elif choice < 0.83 and kind == 'wfq':
            events.append(['weight', rng.choice(flows), rng.randint(1, 8)])
        elif choice < 0.92:
            name = rng.randint(0, 5)
            saved.append(name)
            events.append(['save', name])
        elif saved:
            events.append(['restore', rng.choice(saved)])
    cfg = {
        'banks': M, 'load_balancers': L,
        'fifo_bytes': rng.choice([1, 5, 16, 64, 1000]),
        'pifo_bytes': rng.choice([1, 5, 16, 64, 1000]),
        'refill_batch': rng.randint(1, 4),
        'sample_period': rng.randint(1, 6),
        'borders': borders, 'policy': policy, 'events': events,
    }
    return cfg, next_id


def main():
    seed = int(sys.argv[1]) if len(sys.argv) > 1 else 0
    rounds = int(sys.argv[2]) if len(sys.argv) > 2 else 200
    rng = random.Random(seed)
    counter = 0
    for round_index in range(rounds):
        runs = []
        for _ in range(rng.randint(1, 2)):
            cfg, counter = make_run(rng, counter)
            runs.append(cfg)
        request = {'runs': runs}
        expected = ref.run_request(json.loads(json.dumps(request)))
        actual = run_request(json.loads(json.dumps(request)))
        if json.dumps(expected, sort_keys=True) != json.dumps(actual, sort_keys=True):
            print('MISMATCH in round', round_index)
            print(json.dumps(request, indent=1))
            for index, (e, a) in enumerate(zip(expected['runs'], actual['runs'])):
                if json.dumps(e, sort_keys=True) != json.dumps(a, sort_keys=True):
                    print('run', index)
                    print('expected log:', json.dumps(e['log']))
                    print('actual   log:', json.dumps(a['log']))
                    print('expected state:', json.dumps(e['state']))
                    print('actual   state:', json.dumps(a['state']))
            return 1
    print('fuzz ok:', rounds, 'rounds')
    return 0


if __name__ == '__main__':
    sys.exit(main())
PYEOF
